/// <summary>
/// MPJ_3972_SAPPredictor - kscerri - 09/07/2021
/// Parameter to include number of tasks.
/// </summary>
public class METSAPPredictorService extends SysOperationServiceBase
{
    str                     errorMessage;
    public str              infologMessage;


    
}

Method.Source:
    /// <summary>
    /// MPJ_3972_SAPPredictor - kscerri - 09/07/2021
    /// Process the operation of the batch job and creates a header and line accordinly
    /// </summary>
    /// <param name = "_dataContract">object of data</param>
    public void processOperation(METSAPPredictorContract _dataContract)
    {
        CustTransOpen               custTransOpen;
        CustTrans                   custTrans;
        CustTable                   custTable;
        METSAPPredictorHelper       predictorHelper;
        CustVendDisputeStatus       disputeStatus;

        try
        {
            while select custTransOpen
                join PaymReference, RecId from custTrans
                    where custTrans.RecId == custTransOpen.RefRecId
                       && custTrans.AccountNum == custTransOpen.AccountNum
                       && custTrans.TransType == LedgerTransType::Payment
                join custTable
                    where custTable.AccountNum == custTransOpen.AccountNum
            {
                disputeStatus = CustVendDisputeHelper::construct(custTrans.company(), tablenum(CustTrans), custTrans.RecId).parmStatus();
           
                if (disputeStatus != CustVendDisputeStatus::Disputed || disputeStatus != CustVendDisputeStatus::PromiseToPay)
                {
                    switch (custTable.AccountStatement)
                    {
                        case CustAccountStatement::AMEXWeekly: 
                        case CustAccountStatement::AMEXFortnightly:
                        case CustAccountStatement::AMEXMonthly: 
                        case CustAccountStatement::AMEXPeriod:
                            predictorHelper = METSAPPredictorHelper::constructor();
                            predictorHelper.setDates(custTable.AccountStatement);
                            predictorHelper.autoSettelment(custTransOpen, custTrans, custTable);
                            predictorHelper.finalize();
                            break;

                        default:
                            info("@MET:SAPPredictorDefault");
                            break;
                        
                    }
                }
            }
        }
        catch(Exception::CLRError)
        {
            //If an error occurs, check if log header is available
            this.getInfologMessage();
            System.Exception ex = CLRInterop::getLastException();
            errorMessage += ex.Message + ex.ToString();
            info(errorMessage + infologMessage);
            info ("@MET:VendCrossDocFeeErrorHandler");

        }
    }

    ///// <summary>
    ///// MPJ_3972_SAPPredictor - kscerri - 09/07/2021
    ///// This method gets the info of the error into a variable
    ///// </summary>
    private void getInfologMessage()
    {
        SysInfologEnumerator sysInfologEnumerator;
        SysInfologMessageStruct sysInfologMessageStruct;
        errorMessage    = '';
        infologMessage  = '';
        sysInfologEnumerator = SysInfologEnumerator::newData(infolog.infologData());

        while (sysInfologEnumerator.moveNext())
        {
            sysInfologMessageStruct = new SysInfologMessageStruct(sysInfologEnumerator.currentMessage());

            if (sysInfologEnumerator.currentException() == Exception::Error)
            {
                errorMessage += strfmt(sysInfologMessageStruct.message());
            }
            infologMessage += strfmt(sysInfologMessageStruct.message());
        }
    }
